from pathlib import Path
import sys,json,subprocess,statistics,hashlib
sys.path.insert(0,str(Path.cwd()/'tools/qbe_port'))
from compare_v089 import execute,checksum,digest
r=Path.cwd();b=r/'build/public-perf'
j={'sampling_unavailable':'ptrace TRACEME denied (Operation not permitted); no permission/config changes attempted', 'scope':'diagnostic global versus function, fixed inputs; profiling separate from timings','runs':[]}
previous=json.loads((b/'diagnosis-before.json').read_text())
j['runs']=previous['runs']
for name in ['intarray_access','integer_loop']:
 for variant in ['global','function']:
  if name=='intarray_access' and variant=='global':continue
  src=r/'tests/benchmarks/v089'/f'{name}.lsl' if variant=='global' else b/f'{name}_function.lsl'
  row={'name':name,'variant':variant,'source_sha256':digest(src),'samples':[],'builds':[]};j['runs'].append(row)
  bins={}
  for kind,comp in [('v089',Path('/home/antonin/.local/bin/lslc')),('before',b/'frontend-before')]:
   out=b/f'{name}-{variant}-{kind}';bins[kind]=out
   cmd=[comp,src,out]+([b/'backend-before'] if kind=='before' else [])
   rec,_=execute(cmd,60);rec.update(command=[str(x) for x in cmd],kind=kind,binary_sha256=digest(out));row['builds'].append(rec)
  n=2000000 if name=='intarray_access' else 10000000
  row['iterations']=n;expected=f'{checksum(name,n)}\n'.encode()
  for repeat in range(5):
   for kind in (list(bins) if repeat%2==0 else list(reversed(bins))):
    rec,stdout=execute([bins[kind],n],60);assert stdout==expected,(kind,name,stdout,expected)
    rec.update(kind=kind,repeat=repeat,stdout=stdout.decode());row['samples'].append(rec)
  row['medians']={k:statistics.median(s['seconds'] for s in row['samples'] if s['kind']==k) for k in bins}
  print(name,variant,row['medians'],flush=True)
  (b/'diagnosis-before.json').write_text(json.dumps(j,indent=2)+'\n')
  if False:
   for kind in bins:
    log=b/f'profile-{variant}-{kind}.txt'
    cmd=[b/'sample',log,bins[kind],20000000]
    rec,stdout=execute(cmd,60);assert stdout==f'{checksum(name,20000000)}\n'.encode();rec.update(command=[str(x) for x in cmd],stdout=stdout.decode());row.setdefault('profiles',[]).append(rec)
  (b/'diagnosis-before.json').write_text(json.dumps(j,indent=2)+'\n')

