import sys,json,statistics
from pathlib import Path
sys.path.insert(0,str(Path.cwd()/'tools/qbe_port'))
from compare_v089 import execute,checksum,digest
r=Path.cwd();b=r/'build/public-perf';kind=sys.argv[1]
j={'compiler':kind,'compiler_sha256':digest(b/('frontend-'+kind)),'runs':[]}
for name in (sys.argv[2:] or ['intarray_access','integer_loop']):
 for variant in ['global','function']:
  source=r/'tests/benchmarks/v089'/f'{name}.lsl' if variant=='global' else b/f'{name}_function.lsl'
  out=b/f'{name}-{variant}-{kind}';cmd=[b/('frontend-'+kind),source,out,b/'backend-before']
  rec,_=execute(cmd,60);rec.update(command=[str(v) for v in cmd],sha256=digest(out))
  n=2000000 if name=='intarray_access' else 10000000
  row={'name':name,'variant':variant,'build':rec,'iterations':n,'samples':[]};j['runs'].append(row)
  bins={'v089':b/f'{name}-{variant}-v089',kind:out}
  for repeat in range(5):
   for k in (list(bins) if repeat%2==0 else list(reversed(bins))):
    rec,stdout=execute([bins[k],n],60);assert stdout==f'{checksum(name,n)}\n'.encode()
    rec.update(kind=k,repeat=repeat,stdout=stdout.decode());row['samples'].append(rec)
  row['medians']={k:statistics.median(s['seconds'] for s in row['samples'] if s['kind']==k) for k in bins}
  print(name,variant,row['medians'],flush=True)
  (b/f'diagnosis-{kind}.json').write_text(json.dumps(j,indent=2)+'\n')

