from pathlib import Path
import hashlib,json,os,resource,signal,subprocess,time,shutil
root=Path.cwd()
shared=Path('/home/antonin/LSL-QBE')
build=root/'build/public-perf/endurance'
build.mkdir(exist_ok=True)
front=root/'build/qbe-port-tools/native-selfhost/frontend-stage3'
backend=root/'build/qbe-port-tools/native-selfhost/qbe-stage3'
old=Path('/home/antonin/.local/bin/lslc')
original=shared/'tests/qbe_port/comparison-v089-linux-x86_64.json'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
report={'scope':'long public-ABI correctness checks, not a comparative performance benchmark','optimization_commit':'e86f1e9','fixture_commit':'2da7abdedbabf94e4ee916d805b39af735d65e66','compiler_sha256':sha(front),'backend_sha256':sha(backend),'baseline_sha256':sha(old),'runtime_sha256':sha(root/'build/qbe/runtime.o'),'original_comparison_sha256':sha(original),'memory_limit_gib':4,'candidate_repeats':3,'baseline_repeats':1,'cases':[],'complete':False}
report_path=root/'build/public-perf/endurance.json'
def save():report_path.write_text(json.dumps(report,indent=2)+'\n')
def execute(cmd,timeout=60):
 def limit():resource.setrlimit(resource.RLIMIT_AS,(4*1024**3,4*1024**3))
 start=time.monotonic()
 p=subprocess.Popen([str(v) for v in cmd],cwd=root,stdout=subprocess.PIPE,stderr=subprocess.PIPE,start_new_session=True,preexec_fn=limit)
 timed_out=False
 try:stdout,stderr=p.communicate(timeout=timeout)
 except subprocess.TimeoutExpired:
  timed_out=True;os.killpg(p.pid,signal.SIGKILL);stdout,stderr=p.communicate()
 return {'command':[str(v) for v in cmd],'seconds':time.monotonic()-start,'returncode':p.returncode,'timed_out':timed_out,'stdout':stdout.decode(errors='replace'),'stderr':stderr.decode(errors='replace')}
def expected(name,n):
 if name=='function_calls':
  value=1
  for _ in range(n):value=(value*1664525+1013904223)%2147483648
  return str(value)+'\n'
 size=1024 if name=='list_access' else 128
 q,r=divmod(n,size)
 return str(q*size*(size-1)//2+r*(r-1)//2+size*q*(q+1)//2+r*(q+1))+'\n'
try:
 for name,counts in [('function_calls',[2000000,5000000]),('list_access',[1000000,2000000]),('dictionary_access',[1000000,2000000])]:
  source=shared/'tests/benchmarks/v089'/(name+'.lsl')
  # Preserve the source bytes from the frozen comparison in this run's directory.
  snapshot=build/(name+'.lsl');shutil.copyfile(source,snapshot)
  row={'name':name,'source':str(source),'source_sha256':sha(source),'builds':[],'samples':[]}
  report['cases'].append(row);save()
  bins={}
  for kind,compiler in [('v089',old),('fixed',front)]:
   output=build/(name+'-'+kind)
   cmd=[compiler,snapshot,output]
   if kind=='fixed':cmd.append(backend)
   b=execute(cmd);b['kind']=kind;row['builds'].append(b);save()
   if b['returncode']:raise RuntimeError(name+' compile '+kind+' failed')
   b['binary_sha256']=sha(output);bins[kind]=output
  for count in counts:
   oracle=expected(name,count)
   for kind,repeats in [('v089',1),('fixed',3)]:
    for repeat in range(repeats):
     sample=execute([bins[kind],count]);sample.update(kind=kind,repeat=repeat,iterations=count,expected=oracle)
     sample['matches']=sample['returncode']==0 and sample['stdout']==oracle
     row['samples'].append(sample);save()
     print(name,count,kind,repeat,'PASS' if sample['matches'] else 'FAIL',sample['stdout'].strip(),flush=True)
     if not sample['matches']:raise RuntimeError(name+' checksum mismatch')
  row['source_unchanged']=sha(source)==row['source_sha256']
 report['original_comparison_unchanged']=sha(original)==report['original_comparison_sha256']
 report['binaries_unchanged']=sha(front)==report['compiler_sha256'] and sha(backend)==report['backend_sha256'] and sha(old)==report['baseline_sha256']
 report['runtime_unchanged']=sha(root/'build/qbe/runtime.o')==report['runtime_sha256']
 report['complete']=report['original_comparison_unchanged'] and report['binaries_unchanged'] and report['runtime_unchanged'] and all(c['source_unchanged'] for c in report['cases'])
except Exception as e:report['error']=str(e)
report['oracle']='Function recurrence: Python unbounded integer loop, value=(value*1664525+1013904223)%2147483648, start 1. Collections: q,r=divmod(n,size); q*size*(size-1)//2+r*(r-1)//2+size*q*(q+1)//2+r*(q+1), size 1024 or 128.'
report['driver_sha256']=sha(Path(__file__))
save()
raise SystemExit(0 if report['complete'] else 1)

