from pathlib import Path
import json,subprocess,resource,time,sys
sys.path.insert(0,str(Path.cwd()/'tools/qbe_port'))
from compare_v089 import digest,execute
r=Path.cwd();b=r/'build/public-perf';native=r/'build/qbe-port-tools/native-selfhost';front=native/'frontend-stage3';backend=native/'qbe-stage3'
def capture(cmd):
 def cap():resource.setrlimit(resource.RLIMIT_AS,(4*1024**3,4*1024**3))
 start=time.monotonic();p=subprocess.run([str(x) for x in cmd],capture_output=True,timeout=60,cwd=r,preexec_fn=cap)
 return {'command':[str(x) for x in cmd],'returncode':p.returncode,'stdout':p.stdout.decode(),'stderr':p.stderr.decode(),'seconds':time.monotonic()-start}
j={'known_gaps':[],'gc_roots':[]};report=b/'post-checks.json'
for name in ['boxed_int_infrastructure','boxed_int_operations','automatic_gc','gc_raw_buffer']:
 source=r/f'tests/{name}_conformance.lsl';expected=source.with_suffix('.out').read_text();row={'source':str(source),'runs':[]};j['known_gaps'].append(row)
 for kind,compiler in [('before',b/'frontend-before'),('after',front)]:
  out=b/f'control-{name}-{kind}';build,_=execute([compiler,source,out,backend],60);rec=capture([out]);rec.update(kind=kind,build=build,matches_expected=rec['returncode']==0 and rec['stdout']==expected);row['runs'].append(rec)
 row['baseline_equal']=(row['runs'][0]['returncode'],row['runs'][0]['stdout'],row['runs'][0]['stderr'])==(row['runs'][1]['returncode'],row['runs'][1]['stdout'],row['runs'][1]['stderr'])
 assert row['baseline_equal'],row
 print(name,'baseline equivalent;', 'PASS' if row['runs'][1]['matches_expected'] else 'PRE-EXISTING FAILURE',flush=True);report.write_text(json.dumps(j,indent=2)+'\n')
for repeat in range(4):
 rec=capture([b/'final-language/verify-case-3']);assert rec['returncode']==0 and rec['stdout']==Path('tests/qbe/public_gc_roots.out').read_text();j['gc_roots'].append(rec)
# Exercise the shared default-64-bit magic analysis through the legacy target.
legacy=b/'legacy-current';cmd=[front,'compiler/pure/lslc_direct.lsl',legacy,backend];rec,_=execute(cmd,60);j['legacy_build']={'command':[str(x) for x in cmd],**rec,'sha256':digest(legacy)}
source=b/'final-division/constant_division.lsl';out=b/'legacy-division';cmd=[legacy,source,out];rec,_=execute(cmd,60);j['legacy_division_build']={'command':[str(x) for x in cmd],**rec,'sha256':digest(out)}
rec=capture([out]);assert rec['returncode']==0 and rec['stdout']==(b/'final-division/expected.txt').read_text();j['legacy_division_run']=rec
j['complete']=True;report.write_text(json.dumps(j,indent=2)+'\n');print('Legacy target division oracle PASS; additional GC roots PASS',flush=True)
